/* Example: basic body styling */
body {
    background-color: #f5f5f5;
    margin: 0;
    padding: 0;
}

/* Similar: using clamp for font-size */
.heading {
  font-size: clamp(1rem, 2.5vw, 2rem);
}

/* Example: fluid font-size for a heading */
h1 {
  font-size: clamp(1.5rem, 5vw, 3rem);
}

/* Similar fluid margin example */
.element {
  margin: clamp(0.5rem, 3vw, 2rem);
}

